import { Header } from "@/registry/bases/base/blocks/header-05/components/header-05"
import { dictionary } from "@/registry/bases/base/blocks/header-05/header-05-dictionary"

export default async function Page({
  params,
}: {
  params?: Promise<{ lang?: string }>
}) {
  const { lang } = (await params) ?? {}
  const locale = lang === "ar" ? "ar" : "en"
  return (
    <div className="flex min-h-svh flex-col">
      <Header dictionary={dictionary[locale]} lang={locale} />
      <main className="flex-1 bg-muted/40" />
    </div>
  )
}

import { ChevronDownIcon, HeartIcon, ShoppingBagIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { HeaderMobileMenu } from "@/registry/bases/base/blocks/header-05/components/header-05-mobile-menu"
import { HeaderSearch } from "@/registry/bases/base/blocks/header-05/components/header-05-search"

export type HeaderLink = { label: string; href: string }

export type HeaderColumn = {
  title: string
  href: string
  links: HeaderLink[]
}

export type HeaderNavItem = {
  label: string
  href: string
  /** Present → the item opens a full-width mega menu. */
  columns?: HeaderColumn[]
}

export type HeaderDictionary = {
  brand: { name: string; href: string; homeLabel: string }
  topBar: {
    brandsLabel: string
    /** Sister brands on the start side of the utility bar. */
    brands: HeaderLink[]
    userLabel: string
    /** Utility links; one may carry a small hover/focus dropdown. */
    links: (HeaderLink & { menu?: HeaderLink[]; menuLabel?: string })[]
    language: { label: string; name: string; href: string; lang: string }
  }
  nav: { label: string; items: HeaderNavItem[] }
  search: {
    label: string
    placeholder: string
    cancel: string
    clear: string
    popularLabel: string
    popular: string[]
  }
  favorites: { label: string; href: string }
  bag: { label: string; href: string; count: number }
  menu: { open: string; close: string; title: string }
}

export function BrandLogo({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 64 24"
      aria-hidden="true"
      className={cn("h-6 w-16", className)}
      fill="currentColor"
    >
      {/* Abstract wordmark: a slanted bar + three rounded strokes */}
      <path d="M2 20 12 4h6L8 20Z" />
      <rect x="22" y="9" width="12" height="6" rx="3" />
      <rect x="37" y="9" width="12" height="6" rx="3" />
      <rect x="52" y="9" width="10" height="6" rx="3" />
    </svg>
  )
}

function TopBar({
  topBar,
}: {
  topBar: HeaderDictionary["topBar"]
}) {
  return (
    <div className="hidden bg-muted lg:block">
      <div className="flex h-9 items-center justify-between px-12">
        <nav aria-label={topBar.brandsLabel}>
          <ul className="flex items-center gap-x-4 text-xs font-semibold tracking-wide">
            {topBar.brands.map((brand) => (
              <li key={brand.label}>
                <a
                  href={brand.href}
                  className="rounded-sm text-foreground transition-colors hover:text-muted-foreground focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
                >
                  {brand.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>

        <nav aria-label={topBar.userLabel}>
          <ul className="flex items-center gap-x-3 text-xs font-medium text-foreground">
            {topBar.links.map((link) => (
              <li key={link.label} className="flex items-center gap-x-3">
                {link.menu ? (
                  <div className="group relative flex items-center gap-x-0.5">
                    <a href={link.href} className="hover:text-muted-foreground">
                      {link.label}
                    </a>
                    <ChevronDownIcon
                      aria-hidden="true"
                      className="size-3.5 transition-transform group-focus-within:rotate-180 group-hover:rotate-180"
                    />
                    {/* Opens on hover or keyboard focus — no client JS */}
                    <div className="invisible absolute end-0 top-full z-50 w-56 translate-y-1 rounded-md bg-popover py-2 text-popover-foreground opacity-0 shadow-lg ring-1 ring-foreground/10 transition-[opacity,transform,visibility] duration-150 group-focus-within:visible group-focus-within:translate-y-0 group-focus-within:opacity-100 group-hover:visible group-hover:translate-y-0 group-hover:opacity-100">
                      <p className="px-4 pb-1 text-sm font-medium text-muted-foreground">
                        {link.menuLabel ?? link.label}
                      </p>
                      <ul>
                        {link.menu.map((item) => (
                          <li key={item.label}>
                            <a
                              href={item.href}
                              className="block px-4 py-1.5 text-sm hover:bg-muted focus-visible:bg-muted focus-visible:outline-none"
                            >
                              {item.label}
                            </a>
                          </li>
                        ))}
                      </ul>
                    </div>
                  </div>
                ) : (
                  <a href={link.href} className="hover:text-muted-foreground">
                    {link.label}
                  </a>
                )}
                <span aria-hidden="true" className="h-3.5 w-px bg-border" />
              </li>
            ))}
            <li>
              <a
                href={topBar.language.href}
                hrefLang={topBar.language.lang}
                lang={topBar.language.lang}
                aria-label={`${topBar.language.label}: ${topBar.language.name}`}
                className="hover:text-muted-foreground"
              >
                {topBar.language.name}
              </a>
            </li>
          </ul>
        </nav>
      </div>
    </div>
  )
}

function DesktopNav({ nav }: { nav: HeaderDictionary["nav"] }) {
  return (
    <nav aria-label={nav.label} className="hidden h-full lg:block">
      <ul className="flex h-full items-center gap-x-6">
        {nav.items.map((item) => (
          <li key={item.label} className="group flex h-full items-center">
            <a
              href={item.href}
              aria-haspopup={item.columns ? "true" : undefined}
              className="relative flex h-full items-center text-base font-medium text-foreground outline-none after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:origin-center after:scale-x-0 after:bg-foreground after:transition-transform after:duration-200 group-focus-within:after:scale-x-100 group-hover:after:scale-x-100 focus-visible:after:scale-x-100"
            >
              {item.label}
            </a>
            {item.columns && (
              <div className="invisible absolute inset-x-0 top-full z-40 translate-y-1 border-t bg-background opacity-0 shadow-[0_16px_24px_-12px_rgb(0_0_0/0.12)] transition-[opacity,transform,visibility] duration-200 ease-out group-focus-within:visible group-focus-within:translate-y-0 group-focus-within:opacity-100 group-hover:visible group-hover:translate-y-0 group-hover:opacity-100">
                <div className="mx-auto flex max-w-[1200px] justify-center gap-x-12 gap-y-8 px-6 py-9">
                  {item.columns.map((column) => (
                    <div key={column.title} className="min-w-[140px]">
                      <a
                        href={column.href}
                        className="mb-3 block text-[15px] font-medium text-foreground hover:text-muted-foreground"
                      >
                        {column.title}
                      </a>
                      <ul className="space-y-2.5">
                        {column.links.map((link, i) => (
                          <li key={`${link.label}-${i}`}>
                            <a
                              href={link.href}
                              className="block text-[15px] leading-tight text-muted-foreground transition-colors hover:text-foreground"
                            >
                              {link.label}
                            </a>
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </li>
        ))}
      </ul>
    </nav>
  )
}

const iconLink =
  "relative flex size-11 items-center justify-center rounded-full text-foreground transition-colors outline-none hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/50"

export function Header({
  dictionary,
  lang,
  className,
}: {
  dictionary: HeaderDictionary
  lang: "en" | "ar"
  className?: string
}) {
  const dir = lang === "ar" ? "rtl" : "ltr"

  return (
    <header
      dir={dir}
      className={cn("sticky top-0 z-50 bg-background", className)}
    >
      <TopBar topBar={dictionary.topBar} />

      {/* `relative` anchors the mega menus and the search tray full-width */}
      <div className="relative flex h-15 items-center justify-between px-4 lg:px-12">
        <a
          href={dictionary.brand.href}
          aria-label={dictionary.brand.homeLabel}
          className="flex items-center rounded-sm text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
        >
          <BrandLogo />
        </a>

        <DesktopNav nav={dictionary.nav} />

        <div className="flex items-center gap-x-0.5">
          <HeaderSearch search={dictionary.search} />
          <a
            href={dictionary.favorites.href}
            aria-label={dictionary.favorites.label}
            className={cn(iconLink, "max-sm:hidden")}
          >
            <HeartIcon aria-hidden="true" className="size-6" strokeWidth={1.5} />
          </a>
          <a
            href={dictionary.bag.href}
            aria-label={`${dictionary.bag.label}: ${dictionary.bag.count}`}
            className={iconLink}
          >
            <ShoppingBagIcon
              aria-hidden="true"
              className="size-6"
              strokeWidth={1.5}
            />
            {dictionary.bag.count > 0 && (
              <span
                aria-hidden="true"
                className="absolute top-2 end-2 flex size-4 items-center justify-center rounded-full bg-foreground text-[10px] font-semibold text-background"
              >
                {dictionary.bag.count}
              </span>
            )}
          </a>
          <HeaderMobileMenu dictionary={dictionary} lang={lang} />
        </div>
      </div>
    </header>
  )
}

"use client"

import * as React from "react"
import { SearchIcon, XIcon } from "lucide-react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import type { HeaderDictionary } from "@/registry/bases/base/blocks/header-05/components/header-05"

/**
 * A pill (desktop) / icon (phone) trigger that drops a full-width search tray
 * under the header: input, then popular terms filtered live as you type.
 * Closes on Escape, on the scrim, or on Cancel.
 */
export function HeaderSearch({
  search,
}: {
  search: HeaderDictionary["search"]
}) {
  const [open, setOpen] = React.useState(false)
  const [query, setQuery] = React.useState("")
  const inputRef = React.useRef<HTMLInputElement>(null)
  const reduceMotion = useReducedMotion()
  const trayId = React.useId()

  React.useEffect(() => {
    if (!open) return
    inputRef.current?.focus()
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false)
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [open])

  const trimmed = query.trim().toLowerCase()
  const suggestions = trimmed
    ? search.popular.filter((term) => term.toLowerCase().includes(trimmed))
    : search.popular

  return (
    <>
      <button
        type="button"
        aria-label={search.label}
        aria-expanded={open}
        aria-controls={trayId}
        onClick={() => setOpen((value) => !value)}
        className="group flex items-center rounded-full outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
      >
        <span className="hidden h-9 w-45 items-center gap-2 rounded-full bg-muted ps-3.5 text-muted-foreground transition-colors group-hover:bg-accent lg:flex">
          <SearchIcon aria-hidden="true" className="size-5 shrink-0 text-foreground" />
          <span className="text-sm">{search.placeholder}</span>
        </span>
        <span className="flex size-11 items-center justify-center rounded-full text-foreground transition-colors group-hover:bg-muted lg:hidden">
          <SearchIcon aria-hidden="true" className="size-6" strokeWidth={1.5} />
        </span>
      </button>

      <AnimatePresence>
        {open && (
          <>
            <motion.div
              key="scrim"
              aria-hidden="true"
              className="fixed inset-0 z-30 bg-foreground/10"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: reduceMotion ? 0 : 0.15 }}
              onClick={() => setOpen(false)}
            />
            <motion.div
              key="tray"
              id={trayId}
              className="absolute inset-x-0 top-full z-50 border-t bg-background shadow-[0_16px_24px_-12px_rgb(0_0_0/0.12)]"
              initial={{ opacity: 0, y: reduceMotion ? 0 : -8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: reduceMotion ? 0 : -8 }}
              transition={{ duration: reduceMotion ? 0 : 0.2, ease: "easeOut" }}
            >
              <form
                role="search"
                onSubmit={(event) => event.preventDefault()}
                className="mx-auto max-w-[1200px] px-4 py-4 lg:px-10"
              >
                <div className="flex items-center gap-4">
                  <div className="flex flex-1 items-center gap-3 rounded-full bg-muted px-5 py-3 focus-within:ring-3 focus-within:ring-ring/50">
                    <SearchIcon aria-hidden="true" className="size-6 shrink-0" />
                    <input
                      ref={inputRef}
                      type="search"
                      name="q"
                      value={query}
                      onChange={(event) => setQuery(event.target.value)}
                      placeholder={search.placeholder}
                      aria-label={search.label}
                      className="w-full bg-transparent text-lg outline-none placeholder:text-muted-foreground [&::-webkit-search-cancel-button]:hidden"
                    />
                    {query && (
                      <button
                        type="button"
                        aria-label={search.clear}
                        onClick={() => {
                          setQuery("")
                          inputRef.current?.focus()
                        }}
                        className="shrink-0 rounded-full text-muted-foreground hover:text-foreground"
                      >
                        <XIcon aria-hidden="true" className="size-5" />
                      </button>
                    )}
                  </div>
                  <button
                    type="button"
                    onClick={() => setOpen(false)}
                    className="shrink-0 rounded-md px-2 text-sm font-medium transition-colors hover:text-muted-foreground focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
                  >
                    {search.cancel}
                  </button>
                </div>

                {suggestions.length > 0 && (
                  <div className="mt-5">
                    <p className="text-sm text-muted-foreground">
                      {search.popularLabel}
                    </p>
                    <ul className="mt-2 flex flex-wrap gap-2">
                      {suggestions.map((term) => (
                        <li key={term}>
                          <button
                            type="button"
                            onClick={() => {
                              setQuery(term)
                              inputRef.current?.focus()
                            }}
                            className="rounded-full bg-muted px-4 py-2 text-sm transition-colors hover:bg-accent focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
                          >
                            {term}
                          </button>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </form>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  )
}

"use client"

import * as React from "react"
import { MenuIcon, XIcon } from "lucide-react"

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion"
import { Button } from "@/components/ui/button"
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet"
import type { HeaderDictionary } from "@/registry/bases/base/blocks/header-05/components/header-05"

/** Drawer nav for small screens; categories with a mega menu expand in place. */
export function HeaderMobileMenu({
  dictionary,
  lang,
}: {
  dictionary: HeaderDictionary
  lang: "en" | "ar"
}) {
  const [open, setOpen] = React.useState(false)
  const dir = lang === "ar" ? "rtl" : "ltr"
  const close = () => setOpen(false)
  const { nav, topBar, menu } = dictionary

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        render={
          <Button
            variant="ghost"
            size="icon-lg"
            className="size-11 rounded-full lg:hidden"
          />
        }
      >
        <MenuIcon className="size-6" strokeWidth={1.5} />
        <span className="sr-only">{menu.open}</span>
      </SheetTrigger>
      <SheetContent
        dir={dir}
        side={lang === "ar" ? "left" : "right"}
        showCloseButton={false}
        className="w-[85%] gap-0 overflow-y-auto bg-background sm:max-w-sm"
      >
        <div className="flex items-center justify-end p-4">
          <SheetTitle className="sr-only">{menu.title}</SheetTitle>
          <SheetClose
            render={
              <Button variant="ghost" size="icon" className="size-10 rounded-full" />
            }
          >
            <XIcon className="size-6" strokeWidth={1.5} />
            <span className="sr-only">{menu.close}</span>
          </SheetClose>
        </div>

        <nav aria-label={nav.label} className="flex-1 px-2 pb-6">
          <Accordion>
            {nav.items.map((item) =>
              item.columns ? (
                <AccordionItem
                  key={item.label}
                  value={item.label}
                  className="border-b"
                >
                  <AccordionTrigger className="items-center px-4 py-4 text-lg font-medium hover:no-underline **:data-[slot=accordion-trigger-icon]:size-5 **:data-[slot=accordion-trigger-icon]:text-foreground">
                    {item.label}
                  </AccordionTrigger>
                  <AccordionContent className="space-y-4 px-4 pb-5 [&_a]:no-underline">
                    {item.columns.map((column) => (
                      <div key={column.title}>
                        <a
                          href={column.href}
                          onClick={close}
                          className="block py-1 text-[0.95rem] font-medium text-foreground"
                        >
                          {column.title}
                        </a>
                        <ul className="ps-2">
                          {column.links.map((link, i) => (
                            <li key={`${link.label}-${i}`}>
                              <a
                                href={link.href}
                                onClick={close}
                                className="block py-1.5 text-[0.95rem] text-muted-foreground hover:text-foreground"
                              >
                                {link.label}
                              </a>
                            </li>
                          ))}
                        </ul>
                      </div>
                    ))}
                  </AccordionContent>
                </AccordionItem>
              ) : (
                <div key={item.label} className="border-b">
                  <a
                    href={item.href}
                    onClick={close}
                    className="block px-4 py-4 text-lg font-medium"
                  >
                    {item.label}
                  </a>
                </div>
              )
            )}
          </Accordion>

          <ul className="mt-6 space-y-1 px-4">
            {topBar.links.map((link) => (
              <li key={link.label}>
                <a
                  href={link.href}
                  onClick={close}
                  className="block py-2 text-[0.95rem] text-muted-foreground hover:text-foreground"
                >
                  {link.label}
                </a>
              </li>
            ))}
            <li>
              <a
                href={topBar.language.href}
                hrefLang={topBar.language.lang}
                lang={topBar.language.lang}
                aria-label={`${topBar.language.label}: ${topBar.language.name}`}
                className="block py-2 text-[0.95rem] text-muted-foreground hover:text-foreground"
              >
                {topBar.language.name}
              </a>
            </li>
          </ul>

          <ul
            aria-label={topBar.brandsLabel}
            className="mt-6 flex flex-wrap items-center gap-x-5 gap-y-2 px-4 text-sm font-semibold"
          >
            {topBar.brands.map((brand) => (
              <li key={brand.label}>
                <a href={brand.href} onClick={close} className="hover:text-muted-foreground">
                  {brand.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>
      </SheetContent>
    </Sheet>
  )
}

